import pg from './node_modules/pg/lib/index.js';
const startedAt=new Date().toISOString(),start=performance.now();
const pool=new pg.Pool({connectionString:process.env.FLOW_K01_QUERY_ADMIN_URL,max:1,connectionTimeoutMillis:1000,statement_timeout:1500,query_timeout:1800,application_name:'k01-query-headroom'});
let row=null,error=null,closed=false;pool.on('error',e=>{error={code:e.code??'POOL_ERROR'};});
try{row=(await pool.query("SELECT current_setting('max_connections')::int AS maximum,(SELECT count(*)::int FROM pg_stat_activity) AS occupied, current_setting('superuser_reserved_connections')::int+COALESCE(NULLIF(current_setting('reserved_connections',true),''),'0')::int AS reserved")).rows[0];}catch(e){error={code:e.code??'QUERY_ERROR'};}finally{await pool.end();closed=true;}
const available=row?row.maximum-row.occupied-row.reserved:null;const passed=closed&&!error&&available>=34;
console.log(JSON.stringify({startedAt,endedAt:new Date().toISOString(),elapsedMs:performance.now()-start,row,available,required:34,poolClosed:closed,error,passed}));if(!passed)process.exitCode=1;
